	result := make([]memory.EventReference, 0, len(refs))
	for j := 0; j < len(refs); j++ {
		if isSettleNoticeRef(refs[j]) && j%2 == 0 {
			result = append(result, buildSettleFoldRef(refs[j:j+1]))
		}
	}
	return result
}

